package com.project.entity.enterprise;
import com.project.entity.Employee;
import javax.persistence.*; import java.math.BigDecimal; import java.time.LocalDate;
@Entity @Table(name="salary_structures", uniqueConstraints=@UniqueConstraint(columnNames="employee_id"))
public class SalaryStructure { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id; @OneToOne(fetch=FetchType.EAGER) @JoinColumn(name="employee_id",nullable=false,unique=true) private Employee employee; @Column(precision=12,scale=2) private BigDecimal basicSalary=BigDecimal.ZERO; @Column(precision=12,scale=2) private BigDecimal hra=BigDecimal.ZERO; @Column(precision=12,scale=2) private BigDecimal allowances=BigDecimal.ZERO; @Column(precision=12,scale=2) private BigDecimal pf=BigDecimal.ZERO; @Column(precision=12,scale=2) private BigDecimal tax=BigDecimal.ZERO; private LocalDate effectiveFrom; public Long getId(){return id;} public Employee getEmployee(){return employee;} public void setEmployee(Employee v){employee=v;} public BigDecimal getBasicSalary(){return basicSalary;} public void setBasicSalary(BigDecimal v){basicSalary=v;} public BigDecimal getHra(){return hra;} public void setHra(BigDecimal v){hra=v;} public BigDecimal getAllowances(){return allowances;} public void setAllowances(BigDecimal v){allowances=v;} public BigDecimal getPf(){return pf;} public void setPf(BigDecimal v){pf=v;} public BigDecimal getTax(){return tax;} public void setTax(BigDecimal v){tax=v;} public LocalDate getEffectiveFrom(){return effectiveFrom;} public void setEffectiveFrom(LocalDate v){effectiveFrom=v;} public BigDecimal getGross(){return basicSalary.add(hra).add(allowances);} public BigDecimal getTotalDeductions(){return pf.add(tax);} public BigDecimal getNetSalary(){return getGross().subtract(getTotalDeductions());} }
